public record ApiError(String code, String message, String traceId) {}

@ExceptionHandler(NotFoundException.class)
ResponseEntity<ApiError> notFound(NotFoundException ex) {
    return ResponseEntity.status(404)
            .body(new ApiError(ex.getCode(), ex.getMessage(), traceId()));
}

@ExceptionHandler(Exception.class)
ResponseEntity<ApiError> fallback(Exception ex, HttpServletRequest req) {
    log.error("未处理异常: {} {}", req.getMethod(), req.getRequestURI(), ex);
    return ResponseEntity.status(500)
            .body(new ApiError("INTERNAL_ERROR", "服务暂时不可用", traceId()));
}
